zone.script:
if flag("seal1") == 0 {
  set_flag("seal1", 1);
  message("QUARANTINE PROTOCOL: bulkhead 1 seals at the end of this turn. Anyone left behind it is lost!");
  zone_label("bh1_mark", "SEALING");
}

if flag("seal2") == 0 {
  set_flag("seal2", 1);
  message("QUARANTINE PROTOCOL: bulkhead 2 seals at the end of this turn. Anyone left behind it is lost!");
  zone_label("bh2_mark", "SEALING");
}

if flag("seal3") == 0 {
  set_flag("seal3", 1);
  message("QUARANTINE PROTOCOL: bulkhead 3 seals at the end of this turn. Anyone left behind it is lost!");
  zone_label("bh3_mark", "SEALING");
}

if flag("seal4") == 0 {
  set_flag("seal4", 1);
  message("QUARANTINE PROTOCOL: bulkhead 4 seals at the end of this turn. Anyone left behind it is lost!");
  zone_label("bh4_mark", "SEALING");
}

if flag("log5") == 1 {
  let squad = alive_count("player");
  let here = zone_count("pod", "player");
  if squad > 0 && here >= squad { message("The pods launch. Halcyon Deep falls away behind you, singing. Mission complete."); win(); }
  else { message(here + " of " + squad + " in the pods - everyone still themselves has to make it."); }
} else { message("The pods won't launch without the captain's release code - it's in her log on the bridge."); }

tile.script:
if flag("log1") == 0 {
  set_flag("log1", 1);
  set_flag("logs", flag("logs") + 1);
  message("DOCKMASTER'S LOG: Dockmaster Reyes, day 41: The survey drone came back with something stuck to its hull. Kept it in quarantine bay 2. Bulkhead override for the quarters is 7-7-1-Delta. If you're reading this, don't open bay 2.");
  add_insanity(unit, 4);
  zone_label("log1", "DOCKMASTER'S LOG (read)");
  lock_door("bh1", false);
  zone_label("bh1_mark", "BULKHEAD 1 (OPEN)");
  objective("Logs found: " + flag("logs") + " of 5. Bulkhead 1 is unlocked - push on (east)");
}

if flag("log2") == 0 {
  set_flag("log2", 1);
  set_flag("logs", flag("logs") + 1);
  message("CABIN 6 - PERSONAL LOG: Ensign Okafor: Mara stopped talking yesterday. She just sits and hums the same five notes. Everyone in the mess hall is humming it now. I hum it too when I forget not to. Override for hydroponics: 3-0-3-Gamma.");
  add_insanity(unit, 6);
  zone_label("log2", "CABIN 6 - PERSONAL LOG (read)");
  lock_door("bh2", false);
  zone_label("bh2_mark", "BULKHEAD 2 (OPEN)");
  objective("Logs found: " + flag("logs") + " of 5. Bulkhead 2 is unlocked - push on (east)");
}

if flag("log3") == 0 {
  set_flag("log3", 1);
  set_flag("logs", flag("logs") + 1);
  message("BOTANIST'S LOG: Dr. Vasquez: It isn't a plant. It grows along the decking a hand's width a day and it BURNS - the only thing that slows it is fire. I flooded the east planters with fuel. Override for medical: 9-1-2-Sigma.");
  add_insanity(unit, 6);
  zone_label("log3", "BOTANIST'S LOG (read)");
  lock_door("bh3", false);
  zone_label("bh3_mark", "BULKHEAD 3 (OPEN)");
  objective("Logs found: " + flag("logs") + " of 5. Bulkhead 3 is unlocked - push on (east)");
}

if flag("log4") == 0 {
  set_flag("log4", 1);
  set_flag("logs", flag("logs") + 1);
  message("MEDICAL OFFICER'S LOG: Dr. Lin: The infected don't die. They join. Their minds go somewhere - into the big one on the bridge, the Choir. It can reach out and take you if it sees you. Keep your heads down. Command override: 0-0-0-Omega.");
  add_insanity(unit, 8);
  zone_label("log4", "MEDICAL OFFICER'S LOG (read)");
  lock_door("bh4", false);
  zone_label("bh4_mark", "BULKHEAD 4 (OPEN)");
  objective("Logs found: " + flag("logs") + " of 5. Bulkhead 4 is unlocked - push on (east)");
}

if flag("log5") == 0 {
  set_flag("log5", 1);
  set_flag("logs", flag("logs") + 1);
  message("CAPTAIN'S LOG: Captain Hale: I'm sealing myself on the bridge with it. If anyone finds this - the escape pods are behind me. Burn it. Burn all of it. And don't listen to the singing.");
  add_insanity(unit, 8);
  zone_label("log5", "CAPTAIN'S LOG (read)");
  objective("Get everyone still yourself into the escape pods (east of the bridge)");
  zone_label("pod", "ESCAPE PODS - BOARD");
}

mission.script:
// The quarantine protocol: seal bulkhead i (at column xb) and vent everything behind it.
fn seal(i, xb) {
  let lost = 0;
  for id in units("player") {
    if unit_x(id) <= xb {
      message(unit_name(id) + " was caught behind bulkhead " + i + ". Through the port you watch the section vent to space.");
      kill(id);
      lost += 1;
    }
  }
  close_door("bh" + i);
  lock_door("bh" + i, true);
  zone_label("bh" + i + "_mark", "BULKHEAD " + i + " (SEALED)");
  if lost > 0 {
    for id in units("player") { add_insanity(id, 10 * lost); }
  } else {
    message("Bulkhead " + i + " slams shut behind you. The section beyond it vents to space.");
  }
}

set_flag("logs", 0);
set_vine_growth(5);
// The growth: a little in the bay, more in the quarters, the hydroponics hall
// choked with it, and the bridge.
plant_vines(12, 26, 2.0);
plant_vines(26, 3, 2.5);
plant_vines(22, 26, 1.5);
plant_vines(44, 10, 3.0);
plant_vines(52, 26, 3.5);
plant_vines(47, 19, 3.0);
plant_vines(64, 28, 2.0);
plant_vines(86, 20, 4.0);
message("Halcyon Deep Relay. No answer to hails for nine days. Life support is still running.");
message("Find the crew's logs - each one has the override for the next bulkhead. Watch for growth on the deck: it spreads, and it burns.");
objective("Find the dockmaster's log (docking bay, north-east office)");

let xs = [16, 36, 59, 76];
for i in 1..5 {
  if flag("seal" + i) == 1 {
    set_flag("seal" + i, 2);
    seal(i, xs[i - 1]);
  }
}
// The station whispers.
if round % 5 == 0 {
  message("The lights flicker. Somewhere in the walls, a hundred voices hum five notes.");
  for id in units("player") { add_insanity(id, 2); }
}

let squad = alive_count("player");
if flag("log5") == 1 && squad > 0 && zone_count("pod", "player") >= squad {
  message("The pods launch. Halcyon Deep falls away behind you, singing. Mission complete.");
  win();
}

if unit_class(unit) == "symb_choir" {
  message("The Choir shrieks with a hundred voices and falls silent. In your head, at last: quiet.");
  for id in units("player") { add_insanity(id, -25); }
  set_vine_growth(0);
}
